INSERT INTO content (key,value) VALUES ('site','{"announcements":["Free insured shipping across India","Every original ships with a signed certificate","7-day returns on every canvas"],"hero":[{"kicker":"Collection","title":"The Founding Artists","text":"25 independent artists, hand-picked by our Chief Curator. Original canvases from ₹5,000, each signed and certified.","button":"Shop the collection"},{"kicker":"New collection","title":"Rivers & Monsoons","text":"The Hooghly at dusk, Kuttanad after rain, the Ganga at low tide. Water, painted by artists who live beside it.","button":"Explore rivers & water"},{"kicker":"For business","title":"Art for spaces people remember","text":"Curated walls for offices, cafés, homestays and hotels. Buy outright or rent and rotate every 3–6 months.","button":"Art for your space"}],"one_to_watch":"td"}');
